IMPLEMENT_TMPDIR="<TMPDIR>"
# Check ndjson breadcrumb stream for KV output from dispatcher
cat "$IMPLEMENT_TMPDIR/breadcrumbs/"run-step2-dispatch.*.ndjson 2>/dev/null | python3 -c "
import sys, json
for line in sys.stdin:
    line=line.strip()
    if line:
        try:
            obj=json.loads(line)
            if obj.get('type') == 'kv' or 'STATUS' in str(obj) or 'MANIFEST' in str(obj):
                print(line)
        except:
            print(repr(line))
" 2>/dev/null | head -50 || echo "(no kv breadcrumbs)"

echo "---check step2-impl stdout if any---"
ls "$IMPLEMENT_TMPDIR/" | command grep -i "dispatch\|step2-stdout\|step2-output" 2>/dev/null || true
